# Exact-arithmetic, fail-closed verifier. No I/O, no network, no filesystem,
# deterministic; raises on any failed check. stdlib only: fractions, math.
from fractions import Fraction
from math import factorial, gcd

def verify(witness):
    N = int(witness['N'])
    if N != 12:
        raise ValueError('scope is N=12 only')

    # 1. denominators n!-1 must match the witness record exactly
    rec = {int(k): int(v) for k, v in witness['denominators'].items()}
    dens = {}
    for n in range(2, N+1):
        d = factorial(n) - 1
        if rec.get(n) != d:
            raise ValueError('denominator mismatch at n=%d' % n)
        dens[n] = d

    # 2. gcd-certified pairwise coprimality of {n!-1 : 2<=n<=12}
    for a in range(2, N+1):
        for b in range(a+1, N+1):
            if gcd(dens[a], dens[b]) != 1:
                raise ValueError('coprimality fails at %d,%d' % (a, b))

    # 3. exact partial sum L = sum_{n=2}^{12} 1/(n!-1)
    L = Fraction(0)
    for n in range(2, N+1):
        L += Fraction(1, dens[n])

    # 4. proved tail bound at N=12: 2*(N+2)/((N+1)(N+1)!) < 3/(N+1)!
    lhs = Fraction(2*(N+2), (N+1)*factorial(N+1))
    rhs = Fraction(3, factorial(N+1))
    if not lhs < rhs:
        raise ValueError('tail bound inequality fails')
    # term-by-term exact check over 40 tail terms:
    # sum_{k=N+1}^{N+40} 2/k! < 2*(N+2)/((N+1)(N+1)!)
    tail_upper = Fraction(0)
    for k in range(N+1, N+41):
        tail_upper += Fraction(2, factorial(k))
    if not tail_upper < lhs:
        raise ValueError('tail comparison fails')

    # 5. derived interval: S lies strictly in (L, L + 3/13!)
    if not Fraction(0) < rhs:
        raise ValueError('tail width nonpositive')

    # 6. derived 10^-11 cell: locate (L, L+rhs) inside exact 1e11-grid cells
    scale = Fraction(100000000000)
    a = (L * scale)
    b = ((L + rhs) * scale)
    # both endpoints' integer parts must agree or be consecutive, and the
    # whole interval (L, L+rhs) must lie inside one open unit cell
    ia = a.numerator // a.denominator
    ib = b.numerator // b.denominator
    if ib < ia:
        raise ValueError('degenerate cell')
    # the open cell containing the entire interval is (ia, ia+1)/1e11
    # (requires b < ia+1, i.e. interval does not cross a grid point)
    if not b < ia + 1:
        raise ValueError('interval crosses a 1e-11 grid point')

    return {'L_num': L.numerator, 'L_den': L.denominator,
            'cell_low': ia, 'cell_high': ia + 1}
